import{_ as a,o,c as t,a4 as s}from"./chunks/framework.C83Ss68L.js";const u=JSON.parse('{"title":"ADR-0007: WordPress roles are declared in the app, not created over REST","description":"The REST API cannot create roles or attach capabilities, so the adapter declares the model and audits the live site against it.","frontmatter":{"title":"ADR-0007: WordPress roles are declared in the app, not created over REST","description":"The REST API cannot create roles or attach capabilities, so the adapter declares the model and audits the live site against it."},"headers":[],"relativePath":"explanation/decisions/adr-0007-wordpress-roles-declared-not-created.md","filePath":"explanation/decisions/adr-0007-wordpress-roles-declared-not-created.md","lastUpdated":1792333063000}'),r={name:"explanation/decisions/adr-0007-wordpress-roles-declared-not-created.md"};function d(i,e,n,l,c,h){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-0007-wordpress-roles-are-declared-in-the-app-not-created-over-rest" tabindex="-1">ADR-0007: WordPress roles are declared in the app, not created over REST <a class="header-anchor" href="#adr-0007-wordpress-roles-are-declared-in-the-app-not-created-over-rest" aria-label="Permalink to &quot;ADR-0007: WordPress roles are declared in the app, not created over REST&quot;">​</a></h1><p><strong>Status:</strong> Accepted · <strong>Date:</strong> 2026-10-18</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>WordPress roles are created with <code>add_role()</code> and capabilities are attached with <code>add_cap()</code>. Both are PHP APIs. The REST API has no roles endpoint and no capabilities endpoint — the <a href="https://developer.wordpress.org/rest-api/reference/users/" target="_blank" rel="noreferrer">users endpoint</a> only <em>reads</em> <code>roles</code>, <code>capabilities</code> and <code>extra_capabilities</code>, and only with <code>context=edit</code> and an authenticated caller holding <code>list_users</code>.</p><p>That leaves three audiences with three different needs:</p><ol><li><strong>The site</strong>, which must end up with the role and its capabilities. Only PHP can do that: a plugin, an mu-plugin, or <code>wp-cli role add</code>.</li><li><strong>The dashboard</strong>, which owns the user experience and must decide what to show, which routes to guard, and what the policy <em>is</em>.</li><li><strong>The person deploying</strong>, who needs to know whether the site actually matches the declaration instead of assuming it does.</li></ol><p>A fourth problem makes naive adoption worse: <code>wp_update_user()</code> silently drops a role slug the site does not know. The response is a <code>200</code> with the user unchanged, so <code>useWpUpdateUser({ roles })</code> reports success for a grant that never happened. An audit that accepts &quot;no error&quot; as proof inherits that lie.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The WordPress adapter separates <em>declaring</em> the model from <em>applying</em> it, and never pretends the second is possible from JavaScript.</p><p>A role declaration (<code>WpRoleDefinition</code>) carries both capability vocabularies:</p><ul><li><code>capabilities</code> — the toolkit&#39;s namespaced capabilities (<code>orders:read:own</code>), which drive <code>useCan()</code> and the framework guards.</li><li><code>wpCapabilities</code> — WordPress&#39; snake_case names (<code>read_private_orders</code>), the declaration the site must hold.</li></ul><p>They are never derived from one another. <code>orders:read:own</code> is a policy statement; <code>read_private_orders</code> is a WordPress permission. Collapsing them would hide who may touch somebody else&#39;s record.</p><p>On top of the declaration:</p><ul><li><code>useWpSyncRoles()</code> publishes declarations to the access service so guards understand WordPress role slugs. It is explicit, not a side effect of declaring: <code>useCan()</code> throws on an unknown slug by design, and that throw is the signal that the boot sequence is incomplete.</li><li><code>useWpAssignRole()</code> verifies the roles on the response and fails with <code>422</code> when the grant did not land, naming the missing role. Unassignment is idempotent instead, because nothing there can be silently ignored.</li><li><code>useWpAuditRole()</code> compares the declaration against the capabilities WordPress reports for the role&#39;s holders. <code>granted</code> is the intersection across holders — a capability only one holder has is not a capability the role grants. With no holders the status is <code>unverifiable</code>, never <code>verified</code>: an empty list is not proof.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Better.</strong> A no-PHP dashboard gets a real authorization model instead of a role slug string, and gets told — with evidence — when the site disagrees with it. A silently dropped grant can no longer masquerade as a success. Roles, capabilities and guards read one vocabulary, so a route guard and the button that hides itself cannot drift apart.</p><p><strong>Worse.</strong> The deployment still needs a PHP step somewhere (a plugin, an mu-plugin, <code>wp-cli</code>) for a role that does not exist yet; the adapter cannot remove that step, only stop pretending it is unnecessary. An audit needs <code>context=edit</code>, so a subscriber-level token cannot run one. Every role call asks for <code>context=edit</code> and pays the larger payload. And <code>wpCapabilities</code> is declaration-only data: it is never enforced by this toolkit, only compared, so a stale declaration is possible where an enforced one would not be.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="/katanakit-js/guides/wordpress#9-roles-and-capabilities-without-php">WordPress guide — roles and capabilities without PHP</a></li><li><a href="/katanakit-js/guides/access-control">Access Control</a> — the registry the declarations feed.</li></ul>',19)])])}const g=a(r,[["render",d]]);export{u as __pageData,g as default};
